var t=`1256-callaloo`;var n=`world-1256`;var a=`TT`;var o=`central-america-caribbean`;var r=4;var s=48;var l={en:`Callaloo`,ua:`Калалу`};var d={en:`Callaloo is a dish from Trinidad and Tobago featuring yellow onion, garlic, okra, spinach. This home-sized recipe records each ingredient at the step where it is used. Spinach replaces dasheen/taro leaves, which require appropriate preparation; this is callaloo-inspired rather than traditional.`,ua:`Калалу, страва кухні країни Тринідад і Тобаго з такими основними складниками: жовта цибуля, часник, бамія, шпинат. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Шпинат замінює листя дашину/таро, що потребує спеціальної підготовки; страва лише за мотивами калалу.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`okra`,300,`g`],[`coconut-oil`,30,`ml`]]},{en:`Simmer the spinach, pumpkin and okra with coconut milk until soft; purée lightly for Trinidad-style callaloo texture.`,ua:`Тушкуйте шпинат, гарбуз і окру в кокосовому молоці до м’якості; трохи подрібніть до текстури калалу по-тринідадськи.`,t:[`stewing`],m:30,i:[[`spinach`,460,`g`],[`pumpkin`,320,`g`],[`coconut-milk`,480,`ml`],[`thyme`,4,`sprig`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Combine the prepared components from earlier steps gently into the intended final mixture; do not add new ingredients.`,ua:`Обережно змішайте раніше підготовлені компоненти в потрібну масу; нових складників на цьому етапі не додавайте.`,t:[`mixing`],m:6,i:[]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]}];var p={slug:t,id:n,country:`TT`,region:o,servings:4,minutes:48,title:l,text:d,steps:h};export{a as country,p as default,n as id,s as minutes,o as region,r as servings,t as slug,h as steps,d as text,l as title};